import { PlaneGeometry, MeshBasicNodeMaterial, Group, Vector2 } from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeom = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true });

  const gradientColor = () => {
    const vUv = uv();
    const grad = vUv.y;
    const cBottom = THREE.Color.fromHex(colors.surface);
    const cTop = THREE.Color.fromHex(colors.ink);
    return vec4(mix(cBottom, cTop, grad), 0.95);
  };
  backdropMat.colorNode = gradientColor();

  const backdropMesh = new THREE.Mesh(backdropGeom, backdropMat);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasWidth = 512;
  const atlasHeight = 320;

  const aspect = rect.w / rect.h;
  const spriteWidth = 2.4;
  const spriteHeight = spriteWidth / aspect;

  const geometry = new PlaneGeometry(spriteWidth, spriteHeight);
  const material = new MeshBasicNodeMaterial({ transparent: true });

  const spriteMesh = new THREE.Mesh(geometry, material);
  group.add(spriteMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      texture.colorSpace = THREE.SRGBColorSpace;

      const uScale = rect.w / atlasWidth;
      const vScale = rect.h / atlasHeight;
      const uOffset = rect.x / atlasWidth;
      const vOffset = 1.0 - (rect.y + rect.h) / atlasHeight;

      material.mapNode = texture;
      material.colorNode = texture.uv(
        uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset))
      );
      material.needsUpdate = true;
    }).catch((err) => {
      console.error('Failed to load sprite texture:', err);
    });
  }

  const anim = gsap.fromTo(spriteMesh.position,
    { y: -0.2, x: 0.1 },
    { y: 0.2, x: -0.1, duration: 8, ease: 'sine.inOut', yoyo: true, repeat: -1 }
  );

  group.userData = {
    handlers: {},
    cleanup: () => {
      anim.kill();
      geometry.dispose();
      material.dispose();
      backdropGeom.dispose();
      backdropMat.dispose();
    }
  };

  return group;
}
